BEGIN;
CREATE FUNCTION pg_temp.expect(label text,ok boolean) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL %',label;END IF;RAISE NOTICE 'PASS %',label;END$$;
CREATE FUNCTION pg_temp.reject(label text,statement text) RETURNS void LANGUAGE plpgsql AS $$DECLARE rejected boolean:=false;BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN rejected:=true;END;PERFORM pg_temp.expect(label,rejected);END$$;
CREATE TEMP TABLE f(o uuid,o2 uuid,a uuid,s uuid,x uuid,v uuid,v2 uuid,d uuid,stamp timestamptz);
INSERT INTO f SELECT gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),NULL,clock_timestamp()-interval '30 minutes';
INSERT INTO public.vihem_organisations(id,name,slug) SELECT o,'GPS QA','gps-'||o FROM f UNION ALL SELECT o2,'GPS Other','gps-'||o2 FROM f;
INSERT INTO public.vihem_module_registry(module_key,name,description,category) VALUES('fleet_management','Fleet','QA','operations') ON CONFLICT DO NOTHING;
INSERT INTO public.vihem_organisation_modules(organisation_id,module_key,enabled) SELECT o,'fleet_management',true FROM f UNION ALL SELECT o2,'fleet_management',true FROM f;
INSERT INTO auth.users(id,email) SELECT a,a||'@example.invalid' FROM f UNION ALL SELECT s,s||'@example.invalid' FROM f UNION ALL SELECT x,x||'@example.invalid' FROM f;
INSERT INTO public.vihem_profiles(id,organisation_id,name,email,role,active) SELECT a,o,'GPS Admin',a||'@example.invalid','admin',true FROM f UNION ALL SELECT s,o,'GPS Staff',s||'@example.invalid','staff',true FROM f UNION ALL SELECT x,o2,'GPS Other',x||'@example.invalid','admin',true FROM f ON CONFLICT(id) DO UPDATE SET organisation_id=excluded.organisation_id,role=excluded.role,active=true;
INSERT INTO public.vihem_fleet_vehicles(id,organisation_id,name,current_odometer,odometer_unit) SELECT v,o,'Synthetic GPS',2214,'mil' FROM f UNION ALL SELECT v2,o2,'Other GPS',0,'km' FROM f;
GRANT ALL ON f TO authenticated,service_role;
SELECT set_config('request.jwt.claim.sub',a::text,true) FROM f;
SET LOCAL ROLE authenticated;
UPDATE f SET d=public.vihem_fleet_pair_device(v,'990000000000088','FMC003','QA');
RESET ROLE;
UPDATE public.vihem_fleet_telematics_device_assignments SET assigned_at=now()-interval '2 hours' WHERE device_id=(SELECT d FROM f);
SELECT public.vihem_fleet_provision_device(d,o,v,'990000000000088','Synthetic QA hardware ownership') FROM f;
SELECT public.vihem_fleet_ingest_position(jsonb_build_object('imei','990000000000088','message_id','odo-fresh','recorded_at',clock_timestamp()-interval '1 second','received_at',clock_timestamp(),'gps_valid',true,'latitude',57.317,'longitude',15.583,'speed_kmh',0));
SET LOCAL ROLE authenticated;
SELECT public.vihem_fleet_calibrate_gps_odometer(v,27747,NULL) FROM f;
SELECT pg_temp.expect('manual baseline and km to mil conversion',(SELECT current_odometer=2774.7 FROM public.vihem_fleet_vehicles WHERE id=(SELECT v FROM f)));
SELECT pg_temp.reject('stale calibration rejected',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,27748,NULL)',v)) FROM f;
SELECT pg_temp.reject('NaN rejected',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,%L,1)',v,'NaN')) FROM f;
SELECT pg_temp.reject('lower than verified reading rejected',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,27700,1)',v)) FROM f;
SELECT pg_temp.reject('direct estimate writes denied',format('UPDATE public.vihem_fleet_gps_odometer SET baseline_km=99999 WHERE vehicle_id=%L',v)) FROM f;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub',s::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect('staff cannot read GPS estimate',(SELECT count(*)=0 FROM public.vihem_fleet_gps_odometer));
SELECT pg_temp.reject('staff cannot calibrate',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,27748,1)',v)) FROM f;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub',x::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect('other org cannot read GPS estimate',(SELECT count(*)=0 FROM public.vihem_fleet_gps_odometer));
SELECT pg_temp.reject('other org cannot calibrate',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,27748,1)',v)) FROM f;
RESET ROLE;
SET LOCAL ROLE anon;
SELECT pg_temp.reject('anonymous cannot calibrate','SELECT public.vihem_fleet_calibrate_gps_odometer(NULL,27748,1)');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub',a::text,true) FROM f;
UPDATE public.vihem_fleet_telematics_readings SET recorded_at=now()-interval '10 minutes' WHERE device_id=(SELECT d FROM f);
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('stale position cannot anchor a calibration',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,27748,1)',v)) FROM f;
RESET ROLE;
UPDATE public.vihem_fleet_telematics_readings SET recorded_at=clock_timestamp()-interval '1 second',speed_kmh=20 WHERE device_id=(SELECT d FROM f);
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('moving vehicle calibration rejected',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,27748,1)',v)) FROM f;
RESET ROLE;
UPDATE public.vihem_fleet_telematics_readings SET speed_kmh=0 WHERE device_id=(SELECT d FROM f);
CREATE FUNCTION pg_temp.fail_odometer_event() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'QA audit failure';END$$;
CREATE TRIGGER gps_odo_qa_fail BEFORE INSERT ON public.vihem_fleet_events FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_odometer_event();
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('audit failure rolls back calibration',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,27748,1)',v)) FROM f;
RESET ROLE;
DROP TRIGGER gps_odo_qa_fail ON public.vihem_fleet_events;
SELECT pg_temp.expect('no partial baseline, meter or history',(SELECT baseline_km=27747 AND calibration_revision=1 FROM public.vihem_fleet_gps_odometer WHERE vehicle_id=(SELECT v FROM f)) AND (SELECT count(*)=1 FROM public.vihem_fleet_meter_readings WHERE vehicle_id=(SELECT v FROM f)) AND (SELECT current_odometer=2774.7 FROM public.vihem_fleet_vehicles WHERE id=(SELECT v FROM f)));
-- Move only the synthetic clock/anchor backwards to exercise long reporting gaps without future samples.
UPDATE public.vihem_fleet_gps_odometer SET baseline_at=now()-interval '41 minutes',last_at=now()-interval '40 minutes' WHERE vehicle_id=(SELECT v FROM f);
CREATE FUNCTION pg_temp.odo_point(ident text,minutes_ago integer,lat numeric,speed numeric) RETURNS void LANGUAGE sql AS $$
INSERT INTO public.vihem_fleet_telematics_readings(device_id,organisation_id,vehicle_id,assignment_id,provider_message_id,recorded_at,received_at,gps_valid,latitude,longitude,speed_kmh,source)
SELECT d,o,v,(SELECT id FROM public.vihem_fleet_telematics_device_assignments WHERE device_id=d AND unassigned_at IS NULL),ident,now()-make_interval(mins=>minutes_ago),now(),true,lat,15.583,speed,'traccar' FROM f ON CONFLICT DO NOTHING $$;
SELECT pg_temp.odo_point('odo-a',39,57.318,20);
SELECT pg_temp.odo_point('odo-b',38,57.319,20);
SELECT pg_temp.expect('GPS segment distance added accurately',(SELECT distance_km BETWEEN 0.222 AND 0.223 FROM public.vihem_fleet_gps_odometer WHERE vehicle_id=(SELECT v FROM f)));
SELECT pg_temp.odo_point('odo-b',38,57.319,20);
SELECT pg_temp.expect('duplicate position does not double-count',(SELECT distance_km BETWEEN 0.222 AND 0.223 FROM public.vihem_fleet_gps_odometer WHERE vehicle_id=(SELECT v FROM f)));
SELECT pg_temp.odo_point('odo-late',39,57.3185,20);
SELECT pg_temp.odo_point('odo-gap',28,57.320,20);
SELECT pg_temp.odo_point('odo-jump',27,58.320,20);
SELECT pg_temp.expect('late samples, gaps and jumps flagged without invented distance',(SELECT distance_km BETWEEN 0.222 AND 0.223 AND late_samples=1 AND gap_count=1 AND rejected_segments=1 FROM public.vihem_fleet_gps_odometer WHERE vehicle_id=(SELECT v FROM f)));
SELECT pg_temp.expect('estimate does not overwrite verified service meter',(SELECT current_odometer=2774.7 FROM public.vihem_fleet_vehicles WHERE id=(SELECT v FROM f)));
WITH a AS (
 INSERT INTO public.vihem_fleet_telematics_device_assignments(device_id,vehicle_id,assigned_at,unassigned_at)
 SELECT d,v,now()-interval '4 hours',now()-interval '3 hours' FROM f RETURNING id)
INSERT INTO public.vihem_fleet_telematics_readings(device_id,organisation_id,vehicle_id,assignment_id,provider_message_id,recorded_at,received_at,gps_valid,latitude,longitude,speed_kmh,source)
SELECT d,o,v,a.id,'odo-assignment-change',now()-interval '26 minutes',now(),true,58.321,15.583,20,'traccar' FROM f CROSS JOIN a;
SELECT pg_temp.expect('assignment change pauses rather than guesses',(SELECT needs_calibration AND distance_km BETWEEN 0.222 AND 0.223 FROM public.vihem_fleet_gps_odometer WHERE vehicle_id=(SELECT v FROM f)));
DELETE FROM public.vihem_fleet_telematics_readings WHERE device_id=(SELECT d FROM f);
SELECT pg_temp.expect('position retention does not erase accumulated distance',(SELECT distance_km BETWEEN 0.222 AND 0.223 FROM public.vihem_fleet_gps_odometer WHERE vehicle_id=(SELECT v FROM f)));
SELECT pg_temp.odo_point('odo-fresh-2',0,57.317,0);
UPDATE public.vihem_organisation_modules SET enabled=false WHERE organisation_id=(SELECT o FROM f) AND module_key='fleet_management';
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('disabled Fleet module denies calibration',format('SELECT public.vihem_fleet_calibrate_gps_odometer(%L,27800,1)',v)) FROM f;
RESET ROLE;
UPDATE public.vihem_organisation_modules SET enabled=true WHERE organisation_id=(SELECT o FROM f) AND module_key='fleet_management';
SET LOCAL ROLE authenticated;
SELECT public.vihem_fleet_calibrate_gps_odometer(v,27800,1) FROM f;
RESET ROLE;
SELECT pg_temp.expect('new checked reading resets estimate with revision and history',(SELECT baseline_km=27800 AND distance_km=0 AND gap_count=0 AND NOT needs_calibration AND calibration_revision=2 FROM public.vihem_fleet_gps_odometer WHERE vehicle_id=(SELECT v FROM f)) AND (SELECT count(*)=2 FROM public.vihem_fleet_meter_readings WHERE vehicle_id=(SELECT v FROM f)));
UPDATE public.vihem_fleet_gps_odometer SET last_at=now()-interval '91 days' WHERE vehicle_id=(SELECT v FROM f);
SELECT public.vihem_fleet_tracking_maintenance();
SELECT pg_temp.expect('expired location anchor cleared while baseline and distance survive',(SELECT last_lat IS NULL AND last_lon IS NULL AND needs_calibration AND baseline_km=27800 AND distance_km=0 FROM public.vihem_fleet_gps_odometer WHERE vehicle_id=(SELECT v FROM f)));
ROLLBACK;
